// Pobieramy dane z poprzedniego węzła (API NBP)
const tableData = $input.first().json;
const rates = tableData.rates || [];

// Wyszukujemy interesujące nas waluty
const targets = ['USD', 'EUR', 'GBP', 'CHF'];
const selectedRates = rates.filter(r => targets.includes(r.code));

// Formatujemy czytelny raport tekstowy
const date = tableData.effectiveDate;
let report = `📊 **RAPORT KURSU WALUT NBP (${date})**\n\n`;

selectedRates.forEach(r => {
  report += `• **${r.code}** (${r.currency}): ${r.mid.toFixed(4)} PLN\n`;
});

return {
  data_publikacji: date,
  pobranych_walut: rates.length,
  wybrane_waluty: selectedRates,
  raport_tekstowy: report
};
